def D(n):
    return n**3 + 4*n**2 + 6*n + 4

def check_divisibility(n):
    D_n = D(n)
    if D_n == 0:
        # D(n) is strictly positive for n >= 0, so this shouldn't happen.
        return False

    numerator = 20**(n + 1)

    # Check if D_n divides the numerator
    if numerator % D_n == 0:
        return True
    else:
        return False

solutions = []
for n in range(11): # Check for n = 0, 1, ..., 10
    if check_divisibility(n):
        solutions.append(n)

print("Solutions for n in [0, 10]:", solutions)

