def is_2_5_power_refined(k):
    if k <= 0:
        return False
    while k % 2 == 0:
        k //= 2
    while k % 5 == 0:
        k //= 5
    return k == 1

def search_n(N_limit):
    solutions = []
    n = 0
    while True:
        P1 = n + 2
        if P1 > 2**60: # Safety break for P1 to prevent excessively large numbers
            break

        # Check P1: n+2 must be of the form 2^a 5^b
        if is_2_5_power_refined(P1):
            P2 = n**2 + 2*n + 2
            # Check P2: n^2+2n+2 must be of the form 2^c 5^d
            if is_2_5_power_refined(P2):
                # Found a candidate n
                solutions.append(n)

        if n >= N_limit:
            break
        n += 1
    return solutions

# Searching up to n=500 for reasonable coverage
N_LIMIT = 500
solutions = search_n(N_LIMIT)
print(f"Solutions found up to n={N_LIMIT}: {solutions}")
